"use client";

import { useState, useEffect, useCallback } from "react";
import { X, ChevronDown, RefreshCw } from "lucide-react";
import clsx from "clsx";
import { api, type Execution, type ExecutionStep } from "@/lib/api";
import { StatusPill } from "@/components/status-pill";

type Props = {
  workflowId: string;
  open: boolean;
  onClose: () => void;
  // Bumping this number from the parent (e.g. after a new run is
  // triggered) tells the panel to refetch — simpler than the panel polling
  // on its own timer while it might not even be open.
  refreshSignal: number;
};

function formatDuration(started?: string, finished?: string): string | null {
  if (!started || !finished) return null;
  const ms = new Date(finished).getTime() - new Date(started).getTime();
  if (ms < 1000) return `${ms}ms`;
  return `${(ms / 1000).toFixed(2)}s`;
}

function formatTimestamp(iso: string): string {
  return new Date(iso).toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function ExecutionHistoryPanel({ workflowId, open, onClose, refreshSignal }: Props) {
  const [executions, setExecutions] = useState<Execution[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const list = await api.listExecutions(workflowId, 30);
      setExecutions(list);
    } catch {
      setError("Couldn't load execution history.");
    } finally {
      setLoading(false);
    }
  }, [workflowId]);

  useEffect(() => {
    // Fetching when `open` (or refreshSignal) changes is the correct
    // trigger here — this panel is opened via a prop from the parent
    // header button, not a click inside this component, so there's no
    // local event handler to fetch from instead. The newer
    // set-state-in-effect lint rule flags this as a general pattern to be
    // cautious of (it can hide unnecessary effects), but data fetching
    // keyed to a prop transition is exactly the documented exception.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (open) load();
  }, [open, refreshSignal, load]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-40 flex justify-end">
      <div className="absolute inset-0 bg-black/40" onClick={onClose} />
      <div className="relative flex h-full w-full max-w-md flex-col border-l border-border bg-surface shadow-2xl">
        <div className="flex items-center justify-between border-b border-border px-4 py-4">
          <div>
            <h2 className="font-[family-name:var(--font-display)] text-[14px] font-medium text-text-primary">
              Run history
            </h2>
            <p className="mt-0.5 text-[11px] text-text-tertiary">Last 30 executions</p>
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={load}
              className="rounded-md p-1.5 text-text-tertiary transition-colors hover:bg-surface-hover hover:text-text-primary"
              aria-label="Refresh"
            >
              <RefreshCw size={14} className={loading ? "animate-spin" : ""} />
            </button>
            <button
              onClick={onClose}
              className="rounded-md p-1.5 text-text-tertiary transition-colors hover:bg-surface-hover hover:text-text-primary"
              aria-label="Close"
            >
              <X size={16} />
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {error && <p className="p-4 text-[13px] text-accent-red">{error}</p>}

          {!error && !loading && executions.length === 0 && (
            <p className="p-4 text-[13px] text-text-tertiary">No runs yet. Trigger this workflow to see history here.</p>
          )}

          {executions.map((exec) => (
            <ExecutionRow
              key={exec.id}
              execution={exec}
              expanded={expandedId === exec.id}
              onToggle={() => setExpandedId(expandedId === exec.id ? null : exec.id)}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

function ExecutionRow({
  execution,
  expanded,
  onToggle,
}: {
  execution: Execution;
  expanded: boolean;
  onToggle: () => void;
}) {
  const [steps, setSteps] = useState<ExecutionStep[] | null>(null);
  const [loadingSteps, setLoadingSteps] = useState(false);

  // Fetching directly from the click handler (rather than reactively via
  // an effect watching `expanded`) is both simpler and more correct here:
  // the toggle originates from a real click on this exact button, so
  // there's no reason to route it through a prop-watching effect first.
  function handleToggle() {
    onToggle();
    if (steps === null) {
      setLoadingSteps(true);
      api
        .getExecutionSteps(execution.id)
        .then(setSteps)
        .catch(() => setSteps([]))
        .finally(() => setLoadingSteps(false));
    }
  }

  const duration = formatDuration(execution.started_at, execution.finished_at);

  return (
    <div className="border-b border-border">
      <button
        onClick={handleToggle}
        className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left transition-colors hover:bg-surface-hover"
      >
        <div className="flex min-w-0 items-center gap-3">
          <ChevronDown
            size={14}
            className={clsx("shrink-0 text-text-tertiary transition-transform", expanded && "rotate-180")}
          />
          <div className="min-w-0">
            <p className="font-mono text-[12px] text-text-secondary">{formatTimestamp(execution.created_at)}</p>
            {execution.error && (
              <p className="mt-0.5 truncate text-[11px] text-accent-red">{execution.error}</p>
            )}
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {duration && <span className="font-mono text-[11px] text-text-tertiary">{duration}</span>}
          <StatusPill status={execution.status} />
        </div>
      </button>

      {expanded && (
        <div className="border-t border-border bg-base/40 px-4 py-3">
          {loadingSteps && <p className="text-[12px] text-text-tertiary">Loading steps…</p>}
          {!loadingSteps && steps && steps.length === 0 && (
            <p className="text-[12px] text-text-tertiary">No step data recorded for this run.</p>
          )}
          {!loadingSteps && steps && steps.length > 0 && (
            <ul className="flex flex-col gap-2">
              {steps.map((step) => (
                <li key={step.id} className="flex items-start justify-between gap-3 text-[12px]">
                  <div className="min-w-0">
                    <p className="font-mono text-text-secondary">
                      {step.node_id} <span className="text-text-tertiary">({step.node_type})</span>
                    </p>
                    {step.error && <p className="mt-0.5 truncate text-[11px] text-accent-red">{step.error}</p>}
                  </div>
                  <StatusPill status={step.status} />
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}
